svg.script:

    //let _ps_tagId = 't_578edcf1-0635381f';
	//!export-start
    let _ps_tagId = 't_5e837c37-75d949d6'; // Default value, can be bound in Fuxa
    //!export-end
    let tagId = _ps_tagId;
    let translations = {};
    let currentLang = 'en';

    function fetchLanguageFromSettings() {
      console.log('Fetching language from /api/settings...');
      fetch('/api/settings', { credentials: 'include' })
        .then(res => {
          if (!res.ok) throw new Error('Failed to fetch settings');
          return res.json();
        })
        .then(data => {
          if (data.language) {
            currentLang = data.language.toLowerCase();
            console.log('Detected language from API:', currentLang);
          } else {
            console.warn('No language found in settings, defaulting to "en"');
          }
          loadTranslations(currentLang);
        })
        .catch(err => {
          console.error('Error fetching language settings:', err);
          loadTranslations('en');
        });
    }


    // Initiera
    fetchLanguageFromSettings();

    function loadTranslations(lang) {
      const url = `/assets/i18n/${lang}.json`;
      return fetch(url, { credentials: 'include' })
        .then(res => res.json())
        .then(data => {
          translations = data;
          currentLang = lang;
          updateInterface();
          fetchSchedule();
        })
        .catch(err => {
          if (lang !== 'en') return loadTranslations('en');
        });
    }

    function translate(key) {
      return translations[key] || key;
    }

    function updateInterface() {
      document.querySelector('text').textContent = '';
      document.querySelectorAll('text')[1].textContent = translate('schedule-status-on');
      document.querySelectorAll('text')[2].textContent = translate('schedule-status-off');
    }

    function putValue(id, value) {
      if (id === '_ps_tagId') {
        tagId = value;
        fetchSchedule();
      }
    }

    function fetchSchedule() {
      const container = document.getElementById('scheduleArea');
      container.innerHTML = '';

      fetch('/api/schedules', { credentials: 'include' })
        .then(res => res.json())
        .then(data => {
          const schedule = data.find(s => s.tagId === tagId);
          if (!schedule) return;
          updateScheduleDisplay(schedule);
        });
    }

    function createTimeSelects(value, index, type, format) {
      const container = document.createElement('div');
      container.style.display = 'flex';
      container.style.gap = '4px';
      let hour = parseInt(value.split(':')[0]);
      let minute = parseInt(value.split(':')[1]);
      let isPM = false;

      if (format === '12h') {
        isPM = hour >= 12;
        hour = hour % 12 || 12;
      }

      const hourSelect = document.createElement('select');
      hourSelect.className = 'input-field';
      const hourLimit = format === '12h' ? 12 : 23;
      const hourStart = format === '12h' ? 1 : 0;
      for (let h = hourStart; h <= hourLimit; h++) {
        const opt = document.createElement('option');
        opt.value = h;
        opt.textContent = h.toString().padStart(2, '0');
        if (h === hour) opt.selected = true;
        hourSelect.appendChild(opt);
      }

      const minuteSelect = document.createElement('select');
      minuteSelect.className = 'input-field';
      for (let m = 0; m < 60; m++) {
        const opt = document.createElement('option');
        opt.value = m;
        opt.textContent = m.toString().padStart(2, '0');
        if (m === minute) opt.selected = true;
        minuteSelect.appendChild(opt);
      }

      container.appendChild(hourSelect);
      container.appendChild(minuteSelect);

      let ampmSelect = null;
      if (format === '12h') {
        ampmSelect = document.createElement('select');
        ampmSelect.className = 'input-field';
        ['AM', 'PM'].forEach(period => {
          const opt = document.createElement('option');
          opt.value = period;
          opt.textContent = period;
          if ((isPM && period === 'PM') || (!isPM && period === 'AM')) opt.selected = true;
          ampmSelect.appendChild(opt);
        });
        container.appendChild(ampmSelect);
      }

      container.dataset.index = index;
      container.dataset.type = type;

      container._getTimeValue = function () {
        let h = parseInt(hourSelect.value);
        const m = parseInt(minuteSelect.value);
        if (format === '12h') {
          const isPM = ampmSelect.value === 'PM';
          if (h === 12) h = isPM ? 12 : 0;
          else h = isPM ? h + 12 : h;
        }
        return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
      };

      return container;
    }

    function updateScheduleDisplay(schedule) {
      const container = document.getElementById('scheduleArea');
      container.innerHTML = '';

      const days = [translate('schedule-day-sunday'), translate('schedule-day-monday'), translate('schedule-day-tuesday'), translate('schedule-day-wednesday'), translate('schedule-day-thursday'), translate('schedule-day-friday'), translate('schedule-day-saturday')];
      document.querySelector('text').textContent = schedule.name || translate('schedule-editTitle');

      const format = schedule.timeFormat === '12h' ? '12h' : '24h';

      schedule.periods.forEach((p, i) => {
        const y = 80 + i * 40;
        const isOdd = i % 2 === 0;
        const rowRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        rowRect.setAttribute('x', 10);
        rowRect.setAttribute('y', y - 35);
        rowRect.setAttribute('width', 340);
        rowRect.setAttribute('height', 40);
        rowRect.setAttribute('class', isOdd ? 'row-odd' : 'row-even');
        container.appendChild(rowRect);

        const dayText = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        dayText.setAttribute('x', 20);
        dayText.setAttribute('y', y - 13);
        dayText.setAttribute('font-size', '14');
        dayText.setAttribute('fill', 'black');
        dayText.textContent = days[parseInt(p.dayOfWeek)];
        container.appendChild(dayText);

        const startWrapper = document.createElementNS('http://www.w3.org/2000/svg', 'foreignObject');
        startWrapper.setAttribute('x', 150);
        startWrapper.setAttribute('y', y - 29);
        startWrapper.setAttribute('width', 100);
        startWrapper.setAttribute('height', 35);
        const startSelect = createTimeSelects(p.startTime, i, 'start', format);
        startWrapper.appendChild(startSelect);
        container.appendChild(startWrapper);

        const endWrapper = document.createElementNS('http://www.w3.org/2000/svg', 'foreignObject');
        endWrapper.setAttribute('x', 260);
        endWrapper.setAttribute('y', y - 29);
        endWrapper.setAttribute('width', 100);
        endWrapper.setAttribute('height', 35);
        const endSelect = createTimeSelects(p.endTime, i, 'end', format);
        endWrapper.appendChild(endSelect);
        container.appendChild(endWrapper);
      });

      const saveButton = document.createElementNS('http://www.w3.org/2000/svg', 'foreignObject');
      saveButton.setAttribute('x', 20);
      saveButton.setAttribute('y', 80 + schedule.periods.length * 40);
      saveButton.setAttribute('width', 150);
      saveButton.setAttribute('height', 35);
      saveButton.innerHTML = `<button xmlns="http://www.w3.org/1999/xhtml" class="save-btn">💾 ${translate('schedule-save')}</button>`;
      container.appendChild(saveButton);

      saveButton.querySelector('button').addEventListener('click', () => {
        const wrappers = container.querySelectorAll('foreignObject > div');
        wrappers.forEach(wrapper => {
          const index = parseInt(wrapper.dataset.index);
          const type = wrapper.dataset.type;
          const time = wrapper._getTimeValue();
          schedule.periods[index][type + 'Time'] = time;
        });

        fetch(`/api/schedules/${tagId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify(schedule)
        })
        .then(res => res.json())
        .then(() => fetchSchedule());
      });
    }

    loadTranslations(currentLang);
